N = "7-2"


def titulo():
    return t("The atmosphere, weather, and climate", "La atmósfera, el tiempo y el clima")


def anc(en, es):
    return en if C.L == "en" else es


def R(x):
    return f'<span class="raiz">{x}</span>'


def svg_agua():
    tr = {"Sol": "Sun", "Océano": "Ocean", "Tierra": "Land", "Evaporación": "Evaporation", "Transpiración": "Transpiration", "Condensación": "Condensation",
          "El vapor se enfría y forma nubes": "Vapor cools and forms clouds", "Precipitación": "Precipitation", "Escorrentía": "Runoff", "Infiltración": "Infiltration",
          "(agua subterránea)": "(groundwater)", "El ciclo no tiene principio ni final: es siempre la misma agua": "The cycle has no beginning or end: it is always the same water"}
    return C.svg_orig("7-2_0", tr, "Diagram of the water cycle. The Sun heats the ocean surface and causes evaporation: liquid water turns into vapor and rises. Plants add more vapor through transpiration. Higher up, the vapor cools and condenses, forming clouds. When the drops grow big enough, precipitation falls as rain or snow. Part of the water that falls flows over the surface as runoff and returns to the ocean, and part soaks into the ground and becomes groundwater. The cycle has no beginning or end.")


def svg_invernadero():
    tr = {"Superficie de la Tierra": "Earth’s surface", "Capa de gases de efecto invernadero": "Layer of greenhouse gases", "(CO₂, metano, vapor de agua)": "(CO₂, methane, water vapor)",
          "Radiación solar": "Sunlight", "(onda corta)": "(short waves)", "Atraviesa la capa": "Passes through the layer", "Parte escapa": "Some escapes",
          "Radiación infrarroja": "Infrared radiation", "(onda larga, calor)": "(long waves, heat)", "Absorbida y": "Absorbed and", "reemitida": "sent back", "hacia abajo": "down",
          "Sin efecto invernadero la Tierra sería un planeta helado:": "Without the greenhouse effect Earth would be a frozen planet:",
          "el problema no es que exista, sino que se intensifique": "the problem is not that it exists, but that it is getting stronger"}
    return C.svg_orig("7-2_1", tr, "Diagram of the greenhouse effect. Short-wave sunlight comes in from above, passes through the layer of greenhouse gases, and reaches Earth’s surface. The surface warms up and gives off long-wave infrared radiation upward. Part of that infrared radiation escapes to space, but another part is absorbed by the greenhouse gases and sent back toward the surface, so the heat stays in the system. The conclusion is that the greenhouse effect is natural and essential: without it the planet’s average temperature would be far below freezing. What changes the climate is not that it exists, but that it is getting stronger as the gases increase.")


def svg_serie():
    tr = {"Años (serie larga)": "Years (long series)", "Valor": "Value", "Línea de tendencia": "Trend line", "Dato de cada año": "Each year’s value", "bajó respecto": "dropped from", "al año anterior": "the year before",
          "también bajó, pero sigue muy": "also dropped, but is still far", "por encima del inicio": "above the start", "Un descenso puntual no contradice una tendencia ascendente": "A one-year drop does not contradict a rising trend"}
    return C.svg_orig("7-2_2", tr, "Sketch of a time series with a rising trend and ups and downs from year to year. The horizontal axis is years and the vertical axis is the measured value. The data line rises overall from left to right, but with ups and downs: in some years the value drops from the year before, and yet each of those drops is still above the values of earlier decades. A dashed straight line on top shows the overall rising trend. The right reading is that one year’s change does not contradict the trend of the whole.")


