        item(t("Set 2", "Grupo 2"), [(t("“Over the last 30 years, Chicago winters averaged 26 °F.”", "«En los últimos 30 años, los inviernos de Chicago promediaron −3 °C»."), 1), (t("“Bring an umbrella this afternoon.”", "«Lleve paraguas esta tarde»."), 0), (t("“Deserts get less than 10 inches of rain a year.”", "«Los desiertos reciben menos de 250 mm de lluvia al año»."), 1), (t("“Fog will clear by 10 a.m.”", "«La niebla se disipará antes de las 10 de la mañana»."), 0), (t("“Hurricanes are more common in late summer.”", "«Los huracanes son más frecuentes al final del verano»."), 1)]),
