def ordenes_invernadero():
    pasos = [t("Sunlight (mostly visible light) passes through the atmosphere.", "La radiación solar (sobre todo luz visible) atraviesa la atmósfera."), t("The surface absorbs it and warms up.", "La superficie la absorbe y se calienta."),
             t("The surface gives off infrared radiation (heat).", "La superficie emite radiación infrarroja (calor)."), t("Greenhouse gases absorb the infrared and send it back out in all directions, including down.", "Los gases de efecto invernadero absorben el infrarrojo y lo reemiten en todas direcciones, también hacia abajo."),
             t("Part of the heat stays, and the planet is warmer than it would be with no atmosphere.", "Parte del calor se queda y el planeta está más caliente de lo que estaría sin atmósfera.")]
    cons = {"1>0": t("The surface can only absorb sunlight that has arrived.", "La superficie solo puede absorber la radiación que ya llegó."), "2>1": t("The surface gives off infrared because it warmed up.", "La superficie emite infrarrojo porque se calentó."),
            "3>2": t("The gases absorb the infrared that the surface gives off.", "Los gases absorben el infrarrojo que emite la superficie."), "4>3": t("Heat stays because the gases sent it back.", "El calor se queda porque los gases lo reemitieron.")}
    return [{"titulo": t("The greenhouse effect · Step by step", "El efecto invernadero · Paso a paso"), "intro": t("Put the five steps in order with ▲ and ▼.", "Ordene los cinco pasos con ▲ y ▼."),
             "pasos": pasos, "inicio": [3, 0, 4, 2, 1], "cons": cons, "general": t("Light in → surface warms → infrared out → gases hold it → warmer planet.", "Entra luz → se calienta la superficie → sale infrarrojo → los gases lo retienen → planeta más cálido.")}]


def banco_lazos():
    O = [t("Positive: it strengthens the change", "Positivo: refuerza el cambio"), t("Negative: it reverses the change", "Negativo: revierte el cambio")]
    d = [(t("Warmer oceans hold less CO₂, so more CO₂ stays in the air, which warms the oceans more.", "Los océanos más cálidos retienen menos CO₂, así que queda más CO₂ en el aire, lo que calienta más los océanos."), 0),
         (t("When you get too hot you sweat, and the sweat evaporating cools you down.", "Cuando hace demasiado calor, se suda, y la evaporación del sudor enfría el cuerpo."), 1),
         (t("Thawing frozen soil (permafrost) releases methane, which warms the air and thaws more soil.", "El suelo helado (permafrost) se descongela y libera metano, que calienta el aire y descongela más suelo."), 0),
         (t("After a meal, blood sugar rises; insulin is released and blood sugar drops back.", "Tras comer sube la glucosa; se libera insulina y la glucosa vuelve a bajar."), 1),
         (t("Less snow uncovers dark ground, which absorbs more sunlight and melts more snow.", "Menos nieve deja al descubierto suelo oscuro, que absorbe más luz y derrite más nieve."), 0),
         (t("A thermostat turns the heater off when the room gets too warm.", "Un termostato apaga la calefacción cuando la habitación se calienta demasiado."), 1),
         (t("Hotter, drier weather causes forest fires that release carbon, which makes it hotter.", "El calor y la sequía provocan incendios forestales que liberan carbono, lo que aumenta el calor."), 0),
         (t("When body temperature drops, you shiver, and the shivering warms you up.", "Cuando baja la temperatura corporal, se tirita, y el temblor calienta el cuerpo."), 1)]
    out = [{"enun": t("What kind of feedback loop is it?", "¿Qué tipo de lazo de retroalimentación es?") + f"<br><strong>{x}</strong>", "ops": O, "ok": k, "enOrden": True,
            "pista": t("Does the response go against the first change or add to it? “Negative” does not mean harmful.", "¿La respuesta va en contra del cambio inicial o lo suma? «Negativo» no significa perjudicial."), "exp": f"<strong>{O[k]}.</strong>"} for x, k in d]
    otras = [(t("Without the greenhouse effect, Earth’s average temperature would be…", "Sin efecto invernadero, la temperatura media de la Tierra estaría…"), [t("far below freezing", "muy por debajo del punto de congelación"), t("about the same", "más o menos igual"), t("much hotter", "mucho más alta")], 0, t("The effect is natural and essential.", "El efecto es natural e imprescindible.")),
             (t("Two cities are at the same latitude, but one has much milder winters. A likely reason is…", "Dos ciudades están a la misma latitud, pero una tiene inviernos mucho más suaves. Una causa probable es…"), [t("a warm ocean current near the milder city", "una corriente oceánica cálida cerca de la ciudad más templada"), t("it is closer to the Sun", "está más cerca del Sol"), t("it has more nitrogen in its air", "su aire tiene más nitrógeno")], 0, t("Currents carry heat; latitude does not decide everything.", "Las corrientes transportan calor; la latitud no lo decide todo.")),
             (t("Ocean currents and winds carry heat from the equator toward the poles by…", "Las corrientes oceánicas y los vientos llevan el calor del ecuador hacia los polos por…"), [t("convection", "convección"), t("conduction only", "solo conducción"), t("reflection", "reflexión")], 0, t("Warm, less dense fluid moves; cool fluid comes back.", "El fluido cálido y menos denso se mueve; el frío regresa."))]
    for q, o, k, e in otras:
        out.append({"enun": f"<p>{q}</p>", "ops": o, "ok": k, "pista": t("Think about energy: what lets it in, what holds it, what carries it.", "Piense en la energía: qué la deja entrar, qué la retiene, qué la transporta."), "exp": e})
    return out


def banco_series():
    rnd = random.Random(72)
    out = []
    for n in range(12):
        tipo = n % 4
        base = rnd.choice([10, 20, 30]); paso = rnd.choice([0.6, 0.8, 1.0])
        anios = list(range(1900, 2021, 10)) if tipo != 1 else list(range(1880, 2021, 10))
        ys = []
        for i, a in enumerate(anios):
            y = base + paso * i + rnd.choice([-1.5, -0.5, 0, 0.5, 1.5])
            ys.append(round(y, 1))
        if tipo == 0:
            k = rnd.randint(4, len(anios) - 2)
            ys[k] = round(ys[k - 1] - 1.8, 1)
            q = t(f"The value dropped in {anios[k]}. What does that tell you?", f"El valor bajó en {anios[k]}. ¿Qué indica eso?")
            ops = [t("One drop does not change the rising trend of the whole series.", "Un descenso no cambia la tendencia ascendente del conjunto."), t("The trend reversed that decade.", "La tendencia se invirtió esa década."), t("The whole series is wrong.", "Toda la serie está mal."), t("The values will keep falling from then on.", "Los valores seguirán bajando desde entonces.")]
            e = t("Trend versus single value.", "Tendencia frente a dato.")
        elif tipo == 1:
            for j in range(len(ys) - 3, len(ys)):
                ys[j] = round(ys[len(ys) - 4] - 0.6 * (j - len(ys) + 4), 1)
            q = t("Someone looks only at the last three points and says the series is going down. What is the problem?", "Alguien mira solo los tres últimos puntos y dice que la serie baja. ¿Cuál es el problema?")
            ops = [t("A short span can suggest a different direction from the whole series.", "Un tramo corto puede sugerir una dirección distinta de la del conjunto."), t("Nothing: the last points always decide the trend.", "Ninguno: los últimos puntos siempre deciden la tendencia."), t("Old data should be ignored.", "Hay que ignorar los datos antiguos."), t("The axis is wrong.", "El eje está mal.")]
            e = t("Choose the span carefully: the full series rises.", "Elegir bien el tramo: la serie completa sube.")
        elif tipo == 2:
            q = t("Which statement about the future is worded carefully?", "¿Qué afirmación sobre el futuro está redactada con prudencia?")
            ops = [t("If the trend continued, the value would keep rising after 2020.", "Si la tendencia se mantuviera, el valor seguiría subiendo después de 2020."), t("In 2050 the value will be exactly double.", "En 2050 el valor será exactamente el doble."), t("The value will stop rising in 2030.", "El valor dejará de subir en 2030."), t("The graph proves what will happen in 2100.", "La gráfica demuestra lo que pasará en 2100.")]
            e = t("Careful extrapolation uses “if the trend continued”.", "La extrapolación prudente usa «si la tendencia se mantuviera».")
        else:
            q = t("Another series (number of cars sold) also rose over the same years. What can you conclude?", "Otra serie (número de autos vendidos) también subió esos mismos años. ¿Qué se puede concluir?")
            ops = [t("The two series match; claiming one causes the other needs a known mechanism.", "Las dos series coinciden; afirmar que una causa la otra exige conocer un mecanismo."), t("Car sales must cause this value to rise.", "Las ventas de autos tienen que causar la subida."), t("The two series cannot be related.", "Las dos series no pueden estar relacionadas."), t("One of the series is false.", "Una de las series es falsa.")]
            e = t("Correlation versus cause.", "Correlación frente a causa.")
        sp = {"tipo": "linea", "xEtq": t("Year", "Año"), "yEtq": t("Measured value", "Valor medido"), "px": 20, "py": 5, "series": [{"nombre": "", "puntos": [[a, y] for a, y in zip(anios, ys)]}]}
        out.append({"enun": "<p>" + t("An illustrative series of yearly measurements:", "Una serie ilustrativa de mediciones:") + "</p>" + C.grafica(sp, C.describe(sp), ancho=480, alto=270, y0=int(min(ys) // 5 * 5 - 5), y1=int(max(ys) // 5 * 5 + 10)) + f"<p><strong>{q}</strong></p>",
                    "ops": ops, "ok": 0, "pista": t("Trend versus single value, choose the span, correlation versus cause, and extrapolate only with “if”.", "Tendencia frente a dato, elegir el tramo, correlación frente a causa, y extrapolar solo con «si»."), "exp": e})
    return out


def practica():
    A = {"en": ["water", "weather-climate", "greenhouse", "series"], "es": ["agua", "tiempo-clima", "invernadero", "series"]}[C.L]
    mods = [
        (A[0], t("The atmosphere and the water cycle", "La atmósfera y el ciclo del agua"), C.om("m1", t("Layers, gases, and the processes that move water.", "Capas, gases y los procesos que mueven el agua."))),
        (A[1], t("Weather or climate?", "¿Tiempo o clima?"), C.clasifica("m2")),
        (A[2], t("The greenhouse effect and feedback loops", "El efecto invernadero y los lazos"), C.orden("m3") + "\n" + C.om("m4", t("Positive or negative? Strengthen or reverse?", "¿Positivo o negativo? ¿Refuerza o revierte?"))),
        (A[3], t("Read long time series", "Lea series temporales largas"), C.om("m5", t("Trend, span, cause, and extrapolation.", "Tendencia, tramo, causa y extrapolación."))),
    ]
    js = (C.js_datos("AGU", banco_agua()) + C.js_datos("TYC", clasif_tiempo_clima()) + C.js_datos("INV", ordenes_invernadero()) + C.js_datos("LAZ", banco_lazos()) + C.js_datos("SER", banco_series()) +
          'creaBanco("m1", AGU);\ncreaClasifica("m2", TYC);\ncreaOrden("m3", INV);\ncreaBanco("m4", LAZ);\ncreaBanco("m5", SER);\n')
    return C.pagina_practica(N, titulo(), t("Four activities · new exercises every time · two tries in each one", "Cuatro actividades · ejercicios nuevos cada vez · dos intentos en cada uno"), mods, js)


